/* The 3D cockpit entry for a cockpit view name, or NULL. */
static inline const TieVrCockpitView* TieVrCockpit_FindView(const char* view_name) {
	if (!view_name)
		return NULL;
	for (size_t i = 0; i < sizeof TIE_VR_COCKPIT_VIEWS / sizeof TIE_VR_COCKPIT_VIEWS[0]; ++i)
		if (strncmp(view_name, TIE_VR_COCKPIT_VIEWS[i].view, 9) == 0)
			return &TIE_VR_COCKPIT_VIEWS[i];
	return NULL;
}

